mapper.select:
select i.item_id, i.name, i.kind, u.name as unitName, i.price, s.name as supplierName, i.is_active as active from item i left join unit u on i.unit_id = u.unit_id left join supplier s on i.supplier_id = s.supplier_id
i.kind = #{kind}
and i.price >= #{priceMin}
and i.price <= #{priceMax}
and i.supplier_id = #{supplierId}
and i.is_active = #{status}
and ( normalization(lower(i.name)) ~ #{keywordRegex} or normalization(lower(s.name)) ~#{keywordRegex} )
order by
i.name i.kind u.name i.price s.name i.is_active
asc desc
limit #{size} offset #{offset}

select count(*)
from item i 
left join supplier s
on i.supplier_id = s.supplier_id 


    i.kind = #{kind}


    and i.price >= #{priceMin}


    and i.price <= #{priceMax}


    and i.supplier_id = #{supplierId}


    and i.is_active = #{status}



    and ( 
      normalization(lower(i.name)) ~ #{keywordRegex}
      or normalization(lower(s.name)) ~#{keywordRegex}
    )

select i.item_id, i.name as item_name, i.kind, s.supplier_id, s.name as supplier_name, u.unit_id, u.name as unit_name, i.price from item i join unit u on i.unit_id = u.unit_id join supplier s on i.supplier_id = s.supplier_id
i.is_active = true and i.unit_id is not null and i.price is not null and i.supplier_id is not null
and i.kind = #{kind}
and i.supplier_id = #{supplierId}
and ( normalization(lower(i.name)) ~ #{keywordRegex} )
order by i.kind asc, i.name asc
limit #{size} offset #{offset}

select count(*)
from item i 
join supplier s
on i.supplier_id = s.supplier_id 

  i.is_active = true
  and i.unit_id is not null
  and i.price is not null
  and i.supplier_id is not null

    and i.kind = #{kind}


    and i.supplier_id = #{supplierId}



    and ( 
      normalization(lower(i.name)) ~ #{keywordRegex}
    )
